"""Monotonicity demo: every proper divisor of a perfect number is deficient.

Demonstrates abundancy_lt_of_dvd_lt and abundancy_le_of_dvd: if d | n and d < n
then A(d) < A(n); in particular for the perfect number n=28, A(28)=2 and every
proper divisor has abundancy strictly below 2.
"""
from fractions import Fraction
from math import isqrt
from typing import List

def divisors(n: int) -> List[int]:
    s, l = [], []
    for i in range(1, isqrt(n) + 1):
        if n % i == 0:
            s.append(i)
            if i != n // i:
                l.append(n // i)
    return s + l[::-1]

def sigma(n: int) -> int:
    return sum(divisors(n))

def abundancy(n: int) -> Fraction:
    return Fraction(sigma(n), n)

def main() -> None:
    n = 28
    An = abundancy(n)
    print(f"A({n}) = {An}  (perfect: {An == 2})")
    for d in divisors(n):
        Ad = abundancy(d)
        # integer cross form sigma(d)*n <= sigma(n)*d (sigma_one_cross_le)
        cross = sigma(d) * n <= sigma(n) * d
        rel = "<" if d < n else "="
        print(f"  d={d:>3}: A(d)={str(Ad):>6} {rel} A(n); cross-form holds: {cross}")

if __name__ == "__main__":
    main()

"""Multiplicativity demo: A(m*n) = A(m)*A(n) when gcd(m,n)=1.

Exercises abundancy_mul_of_coprime across coprime pairs (equality holds) and
non-coprime pairs (equality fails), then uses it to verify the Euclid-Euler
even perfect numbers split as A(2^(p-1)) * A(2^p-1) = 2.
"""
from fractions import Fraction
from math import gcd, isqrt
from typing import List, Tuple

def divisors(n: int) -> List[int]:
    s, l = [], []
    for i in range(1, isqrt(n) + 1):
        if n % i == 0:
            s.append(i)
            if i != n // i:
                l.append(n // i)
    return s + l[::-1]

def abundancy(n: int) -> Fraction:
    return Fraction(sum(divisors(n)), n)

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    return all(n % d for d in range(3, isqrt(n) + 1, 2))

def main() -> None:
    pairs: List[Tuple[int, int]] = [(4, 3), (9, 5), (8, 9), (4, 6), (6, 10)]
    for m, n in pairs:
        lhs, rhs = abundancy(m * n), abundancy(m) * abundancy(n)
        print(f"m={m}, n={n}, gcd={gcd(m,n)}: A(mn)={lhs}, A(m)A(n)={rhs}, equal={lhs==rhs}")
    print("Euclid-Euler split via multiplicativity:")
    for p in range(2, 14):
        mp = 2 ** p - 1
        if is_prime(mp):
            N = 2 ** (p - 1) * mp
            split = abundancy(2 ** (p - 1)) * abundancy(mp)
            print(f"  p={p}: N={N}, A(N)={abundancy(N)}, split={split}")

if __name__ == "__main__":
    main()

