function MONOTONICITY-CERTIFICATE(d, n):
    assert d | n
    lhs <- sigma(d) * n
    rhs <- sigma(n) * d
    if d < n: return (lhs <  rhs)      # A(d) < A(n)
    else:     return (lhs <= rhs)      # A(d) = A(n) when d = n

